  "sources": {
   "packages/core/src/read/address.ts": "// Reading addresses (RFC 5322 4.4): "When interpreting addresses, the route portion SHOULD be
// ignored." The obsolete forms (routes, empty list elements, comments and white space between
// every word) are read; anything that fits no grammar makes the field unreadable, not half-guessed.
import { lex, type Token } from "./lexer.ts";

/** A mailbox as written: display name (unquoted, or null), local part, domain. */
export type ReadMailbox = { name: string | null; local: string; domain: string };
/** A named group and its members, which may be none. */
export type ReadGroup = { group: string; members: ReadMailbox[] };
export type ReadAddress = ReadMailbox | ReadGroup;

type Cursor = { tokens: Token[]; at: number };
const peek = (c: Cursor, n = 0): Token | undefined => c.tokens[c.at + n];
const special = (t: Token | undefined, s: string): boolean => t?.kind === "special" && t.value === s;
const word = (t: Token | undefined): boolean => t?.kind === "atom" || t?.kind === "quoted";
const written = (t: Token): string => (t.kind === "quoted" ? `"${t.value}"` : t.kind === "literal" ? `[${t.value}]` : t.value);

/** RFC 5322 3.2.5, 4.1: words and, in the obsolete form, periods, joined as they were spaced. */
function phrase(c: Cursor): string | null {
  let out: string | null = null;
  for (let t = peek(c); t !== undefined && (word(t) || special(t, ".")); t = peek(c)) {
    out = out === null ? t.value : out + (t.spaced ? " " : "") + t.value;
    c.at++;
  }
  return out;
}

/** RFC 5322 3.4.1, 4.4: a word, then periods and words; a domain may be one literal instead. */
function dotted(c: Cursor, domain: boolean): string | null {
  const first = peek(c);
  if (domain && first?.kind === "literal") return (c.at++, written(first));
  if (first === undefined || !(first.kind === "atom" || (!domain && first.kind === "quoted"))) return null;
  let out = written(first);
  c.at++;
  for (let next = peek(c, 1); special(peek(c), ".") && next !== undefined && (next.kind === "atom" || (!domain && next.kind === "quoted")); next = peek(c, 1)) {
    out += `.${written(next)}`;
    c.at += 2;
  }
  return out;
}

/** RFC 5322 3.4.1: a local part, "@", a domain. */
function addrSpec(c: Cursor, name: string | null): ReadMailbox | null {
  const local = dotted(c, false);
  if (local === null || !special(peek(c), "@")) return null;
  c.at++;
  const domain = dotted(c, true);
  return domain === null ? null : { name, local, domain };
}

/** RFC 5322 3.4, 4.4: an optional name and an address in angle brackets (a route before it dropped), or a bare address. */
function mailbox(c: Cursor): ReadMailbox | null {
  const start = c.at;
  const name = phrase(c);
  if (!special(peek(c), "<")) return (c.at = start, addrSpec(c, null));
  c.at++;
  if (special(peek(c), "@")) {
    while (peek(c) !== undefined && !special(peek(c), ":")) c.at++;
    c.at++;
  }
  const m = addrSpec(c, name);
  return m !== null && special(peek(c), ">") ? (c.at++, m) : null;
}

/** RFC 5322 3.4, 4.4: a group (a phrase, ":", members separated by commas, ";") or a mailbox. */
function address(c: Cursor): ReadAddress | null {
  const start = c.at;
  const name = phrase(c);
  if (name === null || !special(peek(c), ":")) return (c.at = start, mailbox(c));
  c.at++;
  const members: ReadMailbox[] = [];
  while (!special(peek(c), ";")) {
    if (special(peek(c), ",")) {
      c.at++;
      continue;
    }
    const m = mailbox(c);
    if (m === null || !(special(peek(c), ",") || special(peek(c), ";"))) return null;
    members.push(m);
  }
  c.at++;
  return { group: name, members };
}

/** RFC 5322 3.4, 4.4: every address of a list, or null when any element fits no grammar. */
export function readAddresses(text: string): ReadAddress[] | null {
  const { tokens, problem } = lex(text);
  if (problem !== null) return null;
  const c: Cursor = { tokens, at: 0 };
  const out: ReadAddress[] = [];
  while (c.at < tokens.length) {
    if (special(peek(c), ",")) {
      c.at++;
      continue;
    }
    const a = address(c);
    if (a === null || !(c.at === tokens.length || special(peek(c), ","))) return null;
    out.push(a);
  }
  return out;
}

/** RFC 5322 3.4.1: the domain compares ignoring ASCII case, the local part exactly. */
export function sameMailbox(a: ReadMailbox, b: ReadMailbox): boolean {
  // ASCII only, as the writer's sameAddress: toLowerCase would also fold the Kelvin sign to "k".
  const fold = (domain: string) => domain.replace(/[A-Z]/g, (c) => c.toLowerCase());
  return a.local === b.local && fold(a.domain) === fold(b.domain);
}
