   "packages/core/src/read/date.ts": "// A date (RFC 5322 3.3): "the date and time-of-day SHOULD express local time", with the zone
// its offset from Universal Time. It is read only when it is a real moment: 30 February, a
// wrong weekday or a zone of 60 minutes keeps no instant, and RFC 5322 4.3's old forms are read.
import { lex } from "./lexer.ts";

/** An instant and its zone (null when unknown), or no instant and why. */
export type ReadDate = { instant: Date; zone: string | null } | { instant: null; problem: string };

const MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
const DAYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
// RFC 5322 4.3: the obsolete zone names, in minutes east of Universal Time.
const NAMED: Record<string, number> = { ut: 0, gmt: 0, est: -300, edt: -240, cst: -360, cdt: -300, mst: -420, mdt: -360, pst: -480, pdt: -420 };

/** RFC 5322 3.3, 4.3: a date's instant and zone; -0000, military and unknown zones are null. */
export function readDate(text: string): ReadDate {
  const { tokens, problem } = lex(text);
  if (problem !== null) return { instant: null, problem: "not a date" };
  const words = tokens.filter((t) => !(t.kind === "special" && (t.value === "," || t.value === ":"))).map((t) => t.value);
  const weekday = DAYS.indexOf((words[0] ?? "").toLowerCase());
  if (weekday !== -1) words.shift();
  const [day = "", mon = "", yr = "", hh = "", mm = "", ...rest] = words;
  const [ss = "", zone = ""] = rest.length === 2 ? rest : ["00", ...rest];
  const month = MONTHS.indexOf(mon.toLowerCase());
  const two = /^\d\d$/;
  if (!/^\d\d?$/.test(day) || month === -1 || !/^\d{2,4}$/.test(yr) || !two.test(hh) || !two.test(mm) || !two.test(ss) || zone === "" || rest.length > 2) {
    return { instant: null, problem: "not a date" };
  }
  // RFC 5322 4.3: a two-digit year under 50 is 20xx, otherwise 19xx; three digits add 1900.
  const y = Number(yr);
  const year = yr.length === 2 ? (y < 50 ? 2000 : 1900) + y : yr.length === 3 ? 1900 + y : y;
  const numeric = /^([+-])(\d\d)(\d\d)$/.exec(zone);
  // RFC 5322 3.3: a numeric zone is a sign and four digits; anything else signed is no zone.
  if (numeric === null && /^[+-]/.test(zone)) return { instant: null, problem: "not a date" };
  if (numeric !== null && Number(numeric[3]) > 59) return { instant: null, problem: "zone minutes over 59" };
  const minutes = numeric === null ? NAMED[zone.toLowerCase()] : (numeric[1] === "-" ? -1 : 1) * (Number(numeric[2]) * 60 + Number(numeric[3]));
  // RFC 5322 3.3: "-0000" means the zone is unknown; so do military letters and other names.
  const offset = minutes === undefined || zone === "-0000" ? null : minutes;
  if (Number(hh) > 23 || Number(mm) > 59 || Number(ss) > 60) return { instant: null, problem: "not a time of day" };
  // The day is checked before the seconds, so a leap second (60) cannot roll it into the next.
  const date = new Date(0);
  date.setUTCFullYear(year, month, Number(day));
  if (date.getUTCDate() !== Number(day) || date.getUTCMonth() !== month) return { instant: null, problem: "not a day of that month" };
  if (weekday !== -1 && date.getUTCDay() !== weekday) return { instant: null, problem: "day of the week does not match" };
  const seconds = Number(hh) * 3600 + Number(mm) * 60 + Number(ss) - (offset ?? 0) * 60;
  const instant = new Date(date.getTime() + seconds * 1000);
  return { instant, zone: offset === null ? null : zone };
}
