   "packages/core/src/read/decode.ts": "// Decoding (RFC 2045 6.1): "the Content-Transfer-Encoding field is used to indicate the type of
// transformation that has been used in order to represent the body in an acceptable manner for
// transport." The writer's encodings, undone: base64, quoted-printable, and RFC 2047 words.
import type { Part } from "./mime.ts";

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/** RFC 2045 6.8: four characters carry three bytes; characters outside the alphabet are ignored, and "=" ends the data. */
function base64(text: string): Uint8Array {
  const out: number[] = [];
  let bits = 0;
  let count = 0;
  for (const c of text) {
    if (c === "=") break;
    const v = B64.indexOf(c);
    if (v === -1) continue;
    bits = (bits << 6) | v;
    count += 6;
    if (count >= 8) {
      count -= 8;
      out.push((bits >> count) & 0xff);
    }
  }
  return Uint8Array.from(out);
}

/**
 * RFC 2045 6.7: white space at the end of a line is dropped (rule 3); "=" at the end of a line is
 * a soft line break; "=XX" is the byte XX; any other "=" stays.
 */
function quotedPrintable(raw: string): Uint8Array {
  const text = raw.replace(/[ \t]+(?=\r\n|$)/g, "");
  const out: number[] = [];
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    const hex = text.slice(i + 1, i + 3);
    if (c === 0x3d && text.startsWith("\r\n", i + 1)) i += 2;
    else if (c === 0x3d && /^[0-9A-Fa-f]{2}$/.test(hex)) (out.push(parseInt(hex, 16)), (i += 2));
    else out.push(c & 0xff);
  }
  return Uint8Array.from(out);
}

/** RFC 2045 6: a body's text as the bytes it encodes; 7bit, 8bit, binary and unknown are as is. */
export function transferDecode(text: string, encoding: string): Uint8Array {
  const e = encoding.trim().toLowerCase();
  if (e === "base64") return base64(text);
  if (e === "quoted-printable") return quotedPrintable(text);
  return Uint8Array.from(text, (c) => c.charCodeAt(0) & 0xff);
}

/** The WHATWG decoder for a charset, or UTF-8 when it knows no such name. */
function decoder(charset: string): { decode: (bytes: Uint8Array) => string } {
  try {
    return new TextDecoder(charset);
  } catch {
    return new TextDecoder("utf-8");
  }
}

/** RFC 2045 5, 6: one part's text, transfer-decoded and then decoded by its charset. */
export function partText(text: string, part: Part): string {
  const header = text.slice(part.header.start, part.header.end);
  const field = header.split(/\r\n(?![ \t])/).find((f) => /^content-transfer-encoding\s*:/i.test(f));
  const cte = field === undefined ? "7bit" : field.slice(field.indexOf(":") + 1).replace(/\r\n/g, "");
  const bytes = transferDecode(text.slice(part.body.start, part.body.end), cte);
  return decoder(part.params["charset"] ?? "us-ascii").decode(bytes);
}

/** RFC 2047 2, 6.2: each "=?charset?B|Q?text?=" decoded; space between two decoded words dropped. */
export function decodeWords(value: string): string {
  // Split into encoded words and the text between them; a word that does not decode is text.
  const pieces = value.split(/(=\?[^?\s]+\?[BbQq]\?[^?\s]*\?=)/).map((piece) => {
    const word = /^=\?([^?]+)\?([BbQq])\?([^?]*)\?=$/.exec(piece);
    if (word === null) return { text: piece, decoded: false };
    const [, charset = "", kind = "", data = ""] = word;
    const bytes = kind.toUpperCase() === "B" ? base64(data) : quotedPrintable(data.replace(/_/g, " "));
    try {
      return { text: new TextDecoder(charset.replace(/\*.*$/, ""), { fatal: true }).decode(bytes), decoded: true };
    } catch {
      return { text: piece, decoded: false };
    }
  });
  return pieces
    .filter((p, i) => !(/^\s+$/.test(p.text) && pieces[i - 1]?.decoded === true && pieces[i + 1]?.decoded === true))
    .map((p) => p.text)
    .join("");
}
",
   "packages/core/src/read/fields.ts": "// Header fields (RFC 5322 2.2.3): "Unfolding is accomplished by simply removing any CRLF that is
// immediately followed by WSP." Fields are kept in the order they appear, repeats included,
// and every flaw in the header is recorded rather than mended.
import type { Problem } from "./index.ts";

/** One header field: its name as written, its value unfolded and trimmed. */
export type Field = { name: string; value: string };

// RFC 5322 3.6: the fields a message may hold at most once, and the two it must hold.
const ONCE = ["date", "from", "sender", "reply-to", "to", "cc", "bcc", "message-id", "in-reply-to", "references", "subject"];
const REQUIRED = ["date", "from"];

/** RFC 5322 2.2: the header's fields in order, and its problems. */
export function headerFields(text: string): { fields: Field[]; problems: Problem[] } {
  const problems: Problem[] = [];
  const problem = (code: Problem["code"], field: string | null, detail: string) => problems.push({ code, field, detail });
  if (/\r(?!\n)|(?<!\r)\n/.test(text)) problem("bare-line-break", null, "a CR or LF outside a CRLF pair");
  const fields: Field[] = [];
  let long = false;
  for (const line of text.split(/\r\n|\r|\n/)) {
    if (line.length > 998 && !long) {
      long = true;
      problem("line-too-long", null, `a line of ${line.length} characters`);
    }
    const last = fields.at(-1);
    if ((line.startsWith(" ") || line.startsWith("\t")) && last !== undefined) last.value += line;
    else if (line.includes(":")) fields.push({ name: line.slice(0, line.indexOf(":")).trim(), value: line.slice(line.indexOf(":") + 1) });
    else if (line !== "") problem("no-colon", null, line.slice(0, 40));
  }
  for (const f of fields) f.value = f.value.trim();
  const count = (name: string) => fields.filter((f) => f.name.toLowerCase() === name).length;
  for (const name of ONCE) if (count(name) > 1) problem("repeated-field", name, `${count(name)} times`);
  for (const name of REQUIRED) if (count(name) === 0) problem("missing-required", name, "absent");
  return { fields, problems };
}
",
   "packages/core/src/read/index.ts": "// Reading a received message (RFC 5322 3.6): "Each header field SHOULD be treated in its
// unfolded form for further syntactic and semantic evaluation." Mail reads what can be read,
// records a problem for each part that cannot, and never supplies a value in its place.
import { readAddresses, type ReadAddress, type ReadMailbox } from "./address.ts";
import { readDate, type ReadDate } from "./date.ts";
import { headerFields, type Field } from "./fields.ts";
import { readMessageIds } from "./message-id.ts";
import { parseParts, type Part } from "./mime.ts";

export { readAddresses, sameMailbox, type ReadAddress, type ReadGroup, type ReadMailbox } from "./address.ts";
export { readDate, type ReadDate } from "./date.ts";
export { decodeWords, partText, transferDecode } from "./decode.ts";
export { headerFields, type Field } from "./fields.ts";
export { lex, type Token } from "./lexer.ts";
export { readMessageIds } from "./message-id.ts";
export { bodyLines, contentType, MAX_DEPTH, parseParts, partFields, section, type Part, type Range } from "./mime.ts";

export const READ_PROBLEMS = [
  "bare-line-break",
  "line-too-long",
  "no-colon",
  "repeated-field",
  "missing-required",
  "unparsed-value",
  "invalid-date",
  "multipart-no-boundary",
  "multipart-unclosed",
  "too-deep",
] as const;
/** Something in a message that could not be read, where, and what was found. */
export type Problem = { code: (typeof READ_PROBLEMS)[number]; field: string | null; detail: string };

/** A received message as read: every value that could not be read is null. */
export type Read = {
  fields: Field[];
  from: ReadMailbox[] | null;
  sender: ReadMailbox | null;
  replyTo: ReadAddress[] | null;
  to: ReadAddress[] | null;
  cc: ReadAddress[] | null;
  bcc: ReadAddress[] | null;
  subject: string | null;
  date: ReadDate | null;
  messageId: string | null;
  inReplyTo: string[] | null;
  references: string[] | null;
  root: Part;
  problems: Problem[];
};

/** One byte per character: string offsets are byte offsets, and nothing is decoded. */
export function binary(bytes: Uint8Array): string {
  let out = "";
  for (let i = 0; i < bytes.length; i += 8192) out += String.fromCharCode(...bytes.subarray(i, i + 8192));
  return out;
}

/** RFC 5322 3.6: the fields, addresses, identifiers, date and structure of a message. */
export function readMessage(bytes: Uint8Array): Read {
  const text = binary(bytes);
  // RFC 5322 2.1: the header ends at the first empty line, whatever its line breaks.
  const end = text.search(/(?:\r\n|\n|\r(?!\n))(?:\r\n|\n|\r(?!\n))/);
  const { fields, problems } = headerFields(end === -1 ? text : text.slice(0, end));
  const first = (name: string) => fields.find((f) => f.name.toLowerCase() === name)?.value;
  const unread = (name: string, detail: string) => problems.push({ code: "unparsed-value", field: name, detail });
  // Each structured field is read with its grammar; one that fits none is null and a problem.
  const parsed = <T>(name: string, read: (value: string) => T | null): T | null => {
    const value = first(name);
    if (value === undefined) return null;
    const result = read(value);
    if (result === null) unread(name, value.slice(0, 80));
    return result;
  };
  // RFC 5322 3.6.2: From and Sender name mailboxes; a group there is no author.
  const mailboxes = (value: string): ReadMailbox[] | null => {
    const list = readAddresses(value) ?? [];
    const boxes = list.flatMap((a) => ("group" in a ? [] : [a]));
    return boxes.length === 0 || boxes.length !== list.length ? null : boxes;
  };
  // RFC 5322 3.6.2, 3.6.4: Sender is one mailbox, Message-ID one identifier.
  const one = <T>(list: T[] | null): T | null => {
    const [first, ...more] = list ?? [];
    return first === undefined || more.length > 0 ? null : first;
  };
  const from = parsed("from", mailboxes);
  const sender = parsed("sender", (v) => one(mailboxes(v)));
  const messageId = parsed("message-id", (v) => one(readMessageIds(v)));
  const dateText = first("date");
  let date: ReadDate | null = null;
  if (dateText !== undefined) {
    date = readDate(dateText);
    if (date.instant === null) {
      problems.push({ code: date.problem === "not a date" ? "unparsed-value" : "invalid-date", field: "date", detail: date.problem });
    }
  }
  const { root, problems: structure } = parseParts(text);
  return {
    fields,
    from,
    sender,
    replyTo: parsed("reply-to", readAddresses),
    to: parsed("to", readAddresses),
    cc: parsed("cc", readAddresses),
    bcc: parsed("bcc", readAddresses),
    subject: first("subject") ?? null,
    date,
    messageId,
    inReplyTo: parsed("in-reply-to", readMessageIds),
    references: parsed("references", readMessageIds),
    root,
    problems: [...problems, ...structure],
  };
}
