   "packages/core/src/read/lexer.ts": "// The words of a structured header field (RFC 5322 3.2): "Characters will be interpreted as a
// series of tokens." Atoms, quoted strings and domain literals, separated by specials, with
// comments and folding white space between them that carry no meaning and are dropped.

/** One word of a structured field; `spaced` when white space or a comment came before it. */
export type Token = { kind: "atom" | "quoted" | "literal" | "special"; value: string; spaced: boolean };

// RFC 5322 3.2.3: atext; RFC 6532 3.2: any character beyond ASCII is atext too.
const ATEXT = /[A-Za-z0-9!#$%&'*+\-/=?^_`{|}~\u0080-￿]/;
const SPACE = /[ \t\r\n]/;

/** RFC 5322 3.2: the tokens of a field body, and the problem that stopped it, if any. */
