import { headerFields, type Field } from "./fields.ts";
import type { Problem } from "./index.ts";

/** [start, end) into the stored bytes, as a binary string's offsets. */
export type Range = { start: number; end: number };

/** One part: where its header and body are, its type and parameters, and what it holds. */
export type Part = {
  header: Range;
  body: Range;
  type: string;
  params: Record<string, string>;
  children: Part[];
  message: Part | null;
};

