// nests thousands to exhaust the stack.
export const MAX_DEPTH = 50;

/** RFC 2045 5.1: a Content-Type value's "type/subtype" (lowercased) and parameters, plain or quoted; names compare without case, the last of a name wins. */
export function contentType(value: string): { type: string; params: Record<string, string> } {
  const params: Record<string, string> = {};
  for (const [, name = "", raw = "", quoted] of value.matchAll(/;\s*([^=;\s]+)\s*=\s*("((?:\\.|[^"\\])*)"|[^;\s]+)/g)) {
