    msg = email.message_from_bytes(open(f"fixtures/{name}.eml", "rb").read(), policy=policy.compat32)
    leaves = []
    def walk(m, path):
        if m.is_multipart():
            for i, p in enumerate(m.get_payload(), 1): walk(p, path + [i])
        elif m.get_content_maintype() == "message":
            walk(m.get_payload()[0], path + [1]) if False else leaves.append({"path": ".".join(map(str, path)) or "1", "type": m.get_content_type(), "raw": None, "text": None})
