            raw = m.get_payload(decode=False)
            text = None
            if m.get_content_maintype() == "text":
                text = m.get_payload(decode=True).decode(m.get_content_charset() or "us-ascii", errors="replace")
            leaves.append({"path": ".".join(map(str, path)) or "1", "type": m.get_content_type(), "raw": raw, "text": text})
    walk(msg, [])
    subj = msg.get("Subject")
